          "task": "قم بكتابة برنامج بلغة C# يجسد منطق (استخدام ViewModel داخل Razor)، مع إضافة التحقق من صحة المدخلات وطباعة رسائل توضيحية تدل على اكتمال المعالجة بنجاح.",
